/**
 * Union type for dependencies accepted by Run.After().
 * Can be an activity instance, activity reference, lane reference, or branch reference.
 */
export type Dependency = ActivityInstance<any> | ActivityReference | LaneReference | BranchReference

/**
 * Configuration for a decision branch.
 * The 'else' id is reserved for the fallback branch (no condition).
 */
export interface DecisionBranch {
    /** Unique identifier; 'else' reserved for fallback */
    readonly id: string
    /** Display label */
    readonly label: string
    /** Condition expression; omit for ELSE branch */
    readonly condition?: string
}

type EnforceBranchInvariants<B extends readonly DecisionBranch[]> = {
    readonly [K in keyof B]: B[K] extends DecisionBranch
        ? B[K] extends { id: 'else' }
            ? B[K] & { readonly label: 'Else' }
            : B[K] & { readonly condition: string }
        : B[K]
}

/**
 * Match mode for decision activities.
 * - match_first: Only the first branch whose condition evaluates to true is taken
 * - match_all: All branches whose conditions evaluate to true are taken
 */
export type DecisionMatchType = 'match_first' | 'match_all'

/**
 * Input configuration for Decision activity.
 */
export interface DecisionInputs<B extends readonly DecisionBranch[]> {
    /** Match mode - defaults to 'match_first' */
    type?: DecisionMatchType
    /** Ordered list of branches */
    branches: EnforceBranchInvariants<B>
}

/**
 * Extract branch IDs from a readonly tuple of DecisionBranch.
 * Enables type-safe branch references like `decision.branches.critical`.
 */
export type ExtractBranchIds<B extends readonly DecisionBranch[]> = {
    readonly [K in B[number]['id']]: BranchReference
}

/**
 * Data reference returned by playbook.lane().
 * Provides access to activity outputs, state, and sysId for cross-lane pill references.
 * This prevents using cross-lane activities in `.runAfter()` (use lane references instead).
 */
export type LaneDataReference<T extends Record<string, ActivityReference> = Record<string, ActivityReference>> = {
    [K in keyof T]: {
        outputs: T[K]['outputs']
        state: T[K]['state']
        sysId: T[K]['sysId']
    }
} & LaneReference

