/**
 * Configuration for delaying the start of a lane or activity.
 * Maps to a sys_pd_timer_attributes record.
 *
 * Discriminated by `type`:
 * - `'explicit'`: fixed delay specified as a duration
 * - `'relative'`: delay relative to a datetime, before or after
 * - `'percentage'`: delay as a percentage of time relative to a datetime
 */
export type StartWithDelay =
    | {
          type: 'explicit'
          /** How long to delay before starting */
          duration: Duration
      }
    | {
          type: 'relative'
          /** How long to delay before or after the reference datetime */
          duration: Duration
          /** Reference datetime for the relative calculation */
          relativeDatetime: string
          /** Whether the delay is before or after the reference datetime */
          relativeOperator: 'before' | 'after'
      }
    | {
          type: 'percentage'
          /** Percentage of time (exclusive 0, inclusive 100). Decimals allowed, e.g. 10.5 */
          percentage: number
          /** Reference datetime for the percentage calculation */
          percentageDatetime: string
      }

